namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryValidatePresenceAndIdentity(principal, resource, request, out var denial))
            return denial;
        if (TryValidateState(principal!, resource!, request!, out denial))
            return denial;
        if (TryValidateRequest(principal!, request!, out denial))
            return denial;

        var administrator = principal!.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource!.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request!.Action);

        return DecideValidatedRequest(
            resource,
            request,
            administrator,
            operatorRole,
            auditor,
            owner,
            delegated);
    }

    private static bool TryValidatePresenceAndIdentity(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
        {
            decision = new AccessDecision(false, "missing-context", true);
            return true;
        }

        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateState(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateRequest(
        Principal principal,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (request.MinuteOfDay is < 0 or > 1439)
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision DecideValidatedRequest(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        if (request.BreakGlass)
            return DecideBreakGlass(request, administrator);

        if (TryApplyClassificationRestrictions(resource, request, out var denial))
            return denial;

        return DecideAction(
            resource,
            request,
            administrator,
            operatorRole,
            auditor,
            owner,
            delegated);
    }

    private static AccessDecision DecideBreakGlass(AccessRequest request, bool administrator)
    {
        return administrator && request.StrongAuthentication
            ? new AccessDecision(true, "break-glass", true)
            : new AccessDecision(false, "invalid-break-glass", true);
    }

    private static bool TryApplyClassificationRestrictions(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision DecideAction(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        return request.Action switch
        {
            "delete" => administrator
                ? CreateAllowedDecision(resource, request, delegated)
                : new AccessDecision(false, "administrator-required", true),
            "write" => administrator || operatorRole || owner || delegated
                ? CreateAllowedDecision(resource, request, delegated)
                : new AccessDecision(false, "write-not-authorised", true),
            "read" => administrator || operatorRole || auditor || owner || delegated
                ? CreateAllowedDecision(resource, request, delegated)
                : new AccessDecision(false, "read-not-authorised", false),
            _ => new AccessDecision(false, "unknown-action", true)
        };
    }

    private static AccessDecision CreateAllowedDecision(
        Resource resource,
        AccessRequest request,
        bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        var requiresAudit = outsideBusinessHours || resource.Classification == "restricted";
        return new AccessDecision(true, delegated ? "delegated" : "role-or-ownership", requiresAudit);
    }
}
